from collections import deque

def solve_lift_buttons(text):
    n, s, g, u, d = map(int, text.split())
    dist = [-1] * (n + 1)
    dist[s] = 0
    queue = deque([s])
    while queue:
        x = queue.popleft()
        if x == g:
            break
        for y in (x + u, x - d):
            if 1 <= y <= n and dist[y] == -1:
                dist[y] = dist[x] + 1
                queue.append(y)
    return str(dist[g])
